import { commands, type Result } from "@/bindings";
import type { DictionaryEntry, DictionaryEntryInput } from "./types";

/**
 * Typed façade over the personal-dictionary Tauri commands.
 *
 * `src/bindings.ts` is generated by tauri-specta and does not expose the
 * dictionary commands yet. The command surface is therefore declared locally
 * and the real `commands` object is cast onto it, so every call still travels
 * through the regular Tauri transport and keeps working unchanged once the
 * bindings are regenerated. Nothing here reimplements the transport.
 */

type DictionaryCommands = {
  listDictionaryEntries(
    scope?: string,
  ): Promise<Result<DictionaryEntry[], string>>;
  addDictionaryEntry(
    entry: DictionaryEntryInput,
  ): Promise<Result<DictionaryEntry, string>>;
  updateDictionaryEntry(
    id: number,
    entry: DictionaryEntryInput,
  ): Promise<Result<void, string>>;
  deleteDictionaryEntry(id: number): Promise<Result<void, string>>;
  setDictionaryEntryEnabled(
    id: number,
    enabled: boolean,
  ): Promise<Result<void, string>>;
  importDictionaryEntries(
    entries: DictionaryEntryInput[],
  ): Promise<Result<number, string>>;
  exportDictionaryEntries(path: string): Promise<Result<number, string>>;
  importDictionaryEntriesFromFile(
    path: string,
  ): Promise<Result<number, string>>;
  getDictionaryVocabulary(scope?: string): Promise<Result<string[], string>>;
  applyDictionarySubstitutions(
    text: string,
    scope?: string,
  ): Promise<Result<string, string>>;
};

const dictionaryCommands = commands as unknown as DictionaryCommands;

/** Lists the entries of a scope. Omitting the scope uses the global scope. */
export const listDictionaryEntries = (scope?: string) =>
  dictionaryCommands.listDictionaryEntries(scope);

export const addDictionaryEntry = (entry: DictionaryEntryInput) =>
  dictionaryCommands.addDictionaryEntry(entry);

export const updateDictionaryEntry = (
  id: number,
  entry: DictionaryEntryInput,
) => dictionaryCommands.updateDictionaryEntry(id, entry);

export const deleteDictionaryEntry = (id: number) =>
  dictionaryCommands.deleteDictionaryEntry(id);

export const setDictionaryEntryEnabled = (id: number, enabled: boolean) =>
  dictionaryCommands.setDictionaryEntryEnabled(id, enabled);

export const importDictionaryEntries = (entries: DictionaryEntryInput[]) =>
  dictionaryCommands.importDictionaryEntries(entries);

/**
 * Writes the dictionary to the JSON file the user chose. The backend owns the
 * file format and the filesystem access, so the webview never touches the
 * file itself. Returns how many entries were written.
 */
export const exportDictionaryEntries = (path: string) =>
  dictionaryCommands.exportDictionaryEntries(path);

/**
 * Adds the entries contained in the dictionary file the user chose. The
 * backend skips the entries that already exist and returns how many entries
 * were actually added.
 */
export const importDictionaryEntriesFromFile = (path: string) =>
  dictionaryCommands.importDictionaryEntriesFromFile(path);

export const getDictionaryVocabulary = (scope?: string) =>
  dictionaryCommands.getDictionaryVocabulary(scope);

export const applyDictionarySubstitutions = (text: string, scope?: string) =>
  dictionaryCommands.applyDictionarySubstitutions(text, scope);
